public void saveOwner(Owner owner) throws DataAccessException {
    if (owner.getCustomerCode() == null) {
        owner.setCustomerCode(generateCustomerCode(owner));
    }
    ownerRepository.save(owner);

}

/**
 * Builds an owner's customer code formatted {@code '<LAST3>-<NNNN>'}, where LAST3 is the
 * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
 * sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
 */
private String generateCustomerCode(Owner owner) {
    String lastName = owner.getLastName();
    String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
    int sequence = ownerRepository.findAll().size() + 1;
    return String.format("%s-%04d", last3, sequence);
}

@Override
@Transactional(readOnly = true)
public boolean existsOwnerWithTelephone(String telephone) throws DataAccessException {
    return ownerRepository.existsByTelephone(telephone);
}

/**
 * Counts the existing owners whose firstName and lastName match the given values
 * case-insensitively. Used to record an owner's namesake count at creation time.
 */
@Override
@Transactional(readOnly = true)
public int countOwnersByName(String firstName, String lastName) throws DataAccessException {
    if (firstName == null || lastName == null) {
        return 0;
    }
    return (int) ownerRepository.findAll().stream()
        .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
            && lastName.equalsIgnoreCase(existing.getLastName()))
        .count();
}

